const search=document.querySelector(".systems-search"),query=document.querySelector("#systems-query"),clear=document.querySelector("#systems-clear"),status=document.querySelector("#systems-search-status"),jump=document.querySelector(".systems-jump");function words(e){return e.normalize("NFKD").replace(/\p{M}/gu,"").toLowerCase().match(/[a-z0-9]+/g)??[]}const jumpLinks=new Map([...jump.querySelectorAll("a")].map(e=>[e.hash,e])),groups=[...document.querySelectorAll(".systems-group")].map(e=>({element:e,link:jumpLinks.get(`#${e.id}`),tiles:[...e.querySelectorAll("[data-system]")].map(e=>{const n=e.querySelector(".system-label").firstChild.textContent,t=[n,...e.dataset.aliases.split("|")].map(words);return{tile:e,terms:t.flat(),compact:t.map(e=>e.join(""))}})}));function filter(){const t=words(query.value),n=t.join("");let e=0;for(const{element:o,link:i,tiles:a}of groups){let s=0;for(const{tile:o,terms:i,compact:r}of a){const e=t.every(e=>i.some(t=>t.startsWith(e)))||r.some(e=>e.startsWith(n));o.hidden=!e,e&&(s+=1)}o.hidden=s===0,i.hidden=o.hidden,e+=s}jump.hidden=e===0,clear.hidden=query.value.length===0,t.length===0?status.textContent="":e===0?status.textContent="No systems match. Try another name or abbreviation.":status.textContent=`${e} ${e===1?"system":"systems"} found.`}query.addEventListener("input",filter),clear.addEventListener("click",()=>{query.value="",filter(),query.focus()}),search.hidden=!1,filter()